# ruff: file-ignore[implicit-namespace-package] - standalone contributor script

"""Generate standalone bimanual URDFs from the bundled single-arm descriptions.

Run from the repository root with:
    uv run --extra plugin-rebot-b601 python .github/scripts/generate_bimanual_urdfs.py

Use --check to verify that the generated files are up to date without writing.
"""

from __future__ import annotations

import argparse
from copy import deepcopy
from dataclasses import dataclass
from pathlib import Path

# ElementTree only builds and serializes XML; defusedxml parses the source.
from xml.etree import ElementTree as ET  # ruff: ignore[suspicious-xml-etree-import]

from defusedxml.ElementTree import parse

_ROOT = Path(__file__).resolve().parents[2]


@dataclass(frozen=True)
class Description:
    """Source and destination paths relative to a plugin's URDF asset root."""

    plugin: str
    source: str
    destination: str
    mesh_package: str
    robot_name: str


DESCRIPTIONS = (
    Description(
        "physicalai-rebot-b601-plugin",
        "rebot-b601-dm/urdf/reBot-DevArm_fixend.urdf",
        "rebot-b601-dm/urdf/rebot_b601_bimanual_dm.urdf",
        "rebot-b601-dm",
        "rebot_b601_bimanual_dm",
    ),
    Description(
        "physicalai-rebot-b601-plugin",
        "rebot-b601-rs/urdf/00-arm-rs_asm-v3_joint_frame.urdf",
        "rebot-b601-rs/urdf/rebot_b601_bimanual_rs.urdf",
        "rebot-b601-rs",
        "rebot_b601_bimanual_rs",
    ),
    *(
        Description(
            "physicalai-stararm-plugin",
            f"stararm102/urdf/stararm102_{variant}_description.urdf",
            f"stararm102/urdf/stararm102_bimanual_{variant}_description.urdf",
            "stararm102",
            f"stararm102_bimanual_{variant}",
        )
        for variant in ("ld", "hd", "fl")
    ),
)


def compose(source: Path, *, mesh_package: str, robot_name: str) -> str:
    """Copy an arm twice, preserving geometry, limits, inertias, and mimic behavior.

    Meshes are shared by both arms. Relative mesh references become package URIs
    so a standard URDF loader can resolve them without Studio's path fallback.

    Args:
        source: Trusted local single-arm URDF.
        mesh_package: ROS package containing any relative mesh references.
        robot_name: Name of the resulting bimanual robot.

    Returns:
        UTF-8 XML with left/right mounts at y=+0.2/-0.2 m, matching the SO-101 layout.

    Raises:
        ValueError: If the source is not a robot with exactly one root link.
    """
    arm = parse(source).getroot()
    if arm is None or arm.tag != "robot":
        msg = f"Expected a robot description in {source}"
        raise ValueError(msg)
    links = {link.attrib["name"] for link in arm.findall("link")}
    children = {child.attrib["link"] for child in arm.findall("joint/child")}
    roots = links - children
    if len(roots) != 1:
        msg = f"Expected one root link in {source}, got {sorted(roots)}"
        raise ValueError(msg)
    root_link = next(iter(roots))

    robot = ET.Element("robot", name=robot_name)
    ET.SubElement(robot, "link", name="world")
    # Global materials are shared, like the meshes; arm-local identities need prefixes.
    robot.extend(deepcopy(material) for material in arm.findall("material"))
    for side, offset in (("left", "0 0.2 0"), ("right", "0 -0.2 0")):
        mount = ET.SubElement(robot, "joint", name=f"{side}_mount", type="fixed")
        ET.SubElement(mount, "origin", xyz=offset, rpy="0 0 0")
        ET.SubElement(mount, "parent", link="world")
        ET.SubElement(mount, "child", link=f"{side}_{root_link}")
        for child in arm:
            if child.tag == "material":
                continue
            component = deepcopy(child)
            for element in component.iter():
                for attribute in ("name", "link", "joint"):
                    if attribute in element.attrib and element.tag != "material":
                        element.set(attribute, f"{side}_{element.attrib[attribute]}")
                if element.tag == "mesh":
                    filename = element.attrib["filename"]
                    if not filename.startswith("package://"):
                        element.set("filename", f"package://{mesh_package}/{filename}")
            robot.append(component)
    ET.indent(robot, space="  ")
    header = (
        '<?xml version="1.0" encoding="utf-8"?>\n'
        "<!-- Copyright (C) 2026 Intel Corporation; SPDX-License-Identifier: Apache-2.0 -->\n"
        "<!-- Generated by .github/scripts/generate_bimanual_urdfs.py; do not edit by hand. -->\n"
        f"<!-- Source: {source.name}. Mounts match the SO-101 bimanual layout. -->\n"
    )
    return header + ET.tostring(robot, encoding="unicode") + "\n"


def main() -> int:
    """Generate all five descriptions, or check for stale generated files.

    Returns:
        Zero on success, one if --check finds a missing or outdated file.
    """
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="Check generated files without writing them.")
    args = parser.parse_args()
    stale = False
    for description in DESCRIPTIONS:
        asset_root = _ROOT / "plugins" / "robots" / description.plugin / "urdf"
        target = asset_root / description.destination
        content = compose(
            asset_root / description.source,
            mesh_package=description.mesh_package,
            robot_name=description.robot_name,
        )
        if args.check:
            if not target.is_file() or target.read_text(encoding="utf-8") != content:
                print(f"Outdated or missing: {target.relative_to(_ROOT)}")  # ruff: ignore[print] - CLI output
                stale = True
        else:
            target.write_text(content, encoding="utf-8")
            print(f"Generated {target.relative_to(_ROOT)}")  # ruff: ignore[print] - CLI output
    return int(stale)


if __name__ == "__main__":
    raise SystemExit(main())
